INSERT INTO books (id, title, author, isbn, description, genre_id, publisher_id, book_type_id, created_by, created_on)
VALUES (1, '2020: The Apocalypse', 'Li Juan', '6556784356', 'A chilling science fiction tale that imagines the world on the brink of collapse during the tumultuous year 2020. Li Juan weaves a haunting narrative of survival, resilience, and unexpected hope as society faces unprecedented global challenges that test the limits of humanity.', 6, 1, 1, 'system', CURRENT TIMESTAMP);

INSERT INTO books (id, title, author, isbn, description, genre_id, publisher_id, book_type_id, created_by, created_on)
VALUES (2, 'Children Of Iron', 'Nikki Wolf', '7665438976', 'Set in a post-industrial wasteland, this literary masterpiece follows three siblings born into a society where humans are classified by their utility. As they discover their true heritage, they must navigate a world where compassion is scarce and rebellion means death. Wolf''''s prose is both lyrical and devastating.', 4, 2, 1, 'system', CURRENT TIMESTAMP);

INSERT INTO books (id, title, author, isbn, description, genre_id, publisher_id, book_type_id, created_by, created_on)
VALUES (3, 'Gold In The Dark', 'Richard Roe', '5442280765', 'A mesmerizing fantasy adventure where a young prospector discovers a mysterious substance that glows only in complete darkness. As she unravels its origins, she becomes entangled in an ancient conflict between shadow dwellers and light bearers that could determine the fate of both their realms.', 6, 3, 1, 'system', CURRENT TIMESTAMP);

INSERT INTO books (id, title, author, isbn, description, genre_id, publisher_id, book_type_id, created_by, created_on)
VALUES (4, 'Leagues Of Smoke', 'Pat Candella', '4556789542', 'An atmospheric novel set in a fog-shrouded coastal town where reality blurs with myth. When strange ships appear on the horizon, bringing with them an impenetrable mist, the townspeople must confront their darkest secrets and the ancient legends they''''ve long dismissed as mere superstition.', 4, 4, 2, 'system', CURRENT TIMESTAMP);

INSERT INTO books (id, title, author, isbn, description, genre_id, publisher_id, book_type_id, created_by, created_on)
VALUES (5, 'Alone With The Stars', 'Carlos Salazar', '4563358087', 'A gripping psychological thriller about an astronaut stranded on the International Space Station after a catastrophic event on Earth cuts off all communication. As isolation takes its toll, she begins receiving mysterious radio transmissions that challenge her perception of reality and her will to survive.', 5, 5, 2, 'system', CURRENT TIMESTAMP);

INSERT INTO books (id, title, author, isbn, description, genre_id, publisher_id, book_type_id, created_by, created_on)
VALUES (6, 'The Girl In The Polaroid', 'Terri Whitlock', '2354435678', 'When a vintage Polaroid camera is discovered in an estate sale, the new owner becomes obsessed with a mysterious girl who appears in every photo taken, despite not being present when the pictures were snapped. This haunting mystery blends supernatural elements with a cold-case investigation that spans decades.', 5, 6, 1, 'system', CURRENT TIMESTAMP);

INSERT INTO books (id, title, author, isbn, description, genre_id, publisher_id, book_type_id, created_by, created_on)
VALUES (7, '1001 Jokes', 'Mary Major', '6554789632', 'A hilarious collection of jokes, puns, and witty one-liners for all occasions, curated by renowned comedian Mary Major. From clever wordplay to laugh-out-loud situational humor, this book promises to brighten any day and is perfect for breaking the ice or entertaining friends and family.', 6, 7, 2, 'system', CURRENT TIMESTAMP);

INSERT INTO books (id, title, author, isbn, description, genre_id, publisher_id, book_type_id, created_by, created_on)
VALUES (8, 'My Search For Meaning', 'Mateo Jackson', '4558786554', 'In this profound memoir, Mateo Jackson recounts his journey from tragedy to purpose after losing everything in a natural disaster. Through encounters with diverse philosophies and spiritual traditions, he crafts a deeply personal framework for finding significance in life''''s most challenging moments. A moving testament to human resilience.', 1, 8, 3, 'system', CURRENT TIMESTAMP);

INSERT INTO books (id, title, author, isbn, description, genre_id, publisher_id, book_type_id, created_by, created_on)
VALUES (9, 'The Journey Home', 'Emma Roberts', '9781234567890', 'A poignant memoir chronicling Emma Roberts'''' path from small-town roots to self-discovery. Through vivid storytelling, she reflects on family relationships, personal challenges, and the unexpected moments that shaped her identity. Her honest narrative offers readers both comfort and inspiration for their own life journeys.', 1, 1, 1, 'system', CURRENT TIMESTAMP);

INSERT INTO books (id, title, author, isbn, description, genre_id, publisher_id, book_type_id, created_by, created_on)
VALUES (10, 'The Midnight Detective', 'James Patterson', '9780316412674', 'When a series of bizarre murders rocks a quiet coastal town, Detective Sarah Winters must confront both a cunning killer and her own troubled past. Patterson''''s signature fast-paced narrative delivers unexpected twists as Sarah races against time to prevent the next killing, uncovering a conspiracy that reaches the highest levels of local power.', 5, 2, 2, 'system', CURRENT TIMESTAMP);

INSERT INTO books (id, title, author, isbn, description, genre_id, publisher_id, book_type_id, created_by, created_on)
VALUES (11, 'Becoming', 'Michelle Obama', '9781524763138', 'In this intimate and powerful memoir, Michelle Obama invites readers into her world, chronicling the experiences that shaped her—from her childhood in Chicago to her years balancing motherhood and career to her time at the White House. With honesty and wit, she describes her triumphs and disappointments, both public and private.', 1, 3, 1, 'system', CURRENT TIMESTAMP);

INSERT INTO books (id, title, author, isbn, description, genre_id, publisher_id, book_type_id, created_by, created_on)
VALUES (12, 'Shadows and Starlight', 'Neil Gaiman', '9780062255655', 'In this enchanting fantasy, a young woman discovers a hidden door in her grandmother''''s house that leads to a realm where stars take human form and shadows have their own consciousness. As she navigates this magical world, she uncovers secrets about her family''''s connection to this realm and her own extraordinary destiny.', 6, 4, 1, 'system', CURRENT TIMESTAMP);

INSERT INTO books (id, title, author, isbn, description, genre_id, publisher_id, book_type_id, created_by, created_on)
VALUES (13, 'Murder at Thornfield Manor', 'Agatha Christie', '9780062073488', 'When the wealthy patriarch of Thornfield Manor is found dead in his locked study, everyone in the household becomes a suspect. Christie''''s beloved detective Hercule Poirot must untangle a web of family secrets, hidden motives, and clever deceptions to reveal the killer in this classic whodunit that keeps readers guessing until the final page.', 5, 5, 3, 'system', CURRENT TIMESTAMP);

INSERT INTO books (id, title, author, isbn, description, genre_id, publisher_id, book_type_id, created_by, created_on)
VALUES (14, 'Sapiens: A Brief History of Humankind', 'Yuval Noah Harari', '9780062316097', 'This groundbreaking narrative explores how an insignificant ape rose to become the dominant species on Earth. Harari traces the evolution of Homo sapiens through major historical revolutions—cognitive, agricultural, and scientific—examining how our species has shaped and been shaped by our environment, beliefs, and social structures.', 3, 6, 1, 'system', CURRENT TIMESTAMP);

INSERT INTO books (id, title, author, isbn, description, genre_id, publisher_id, book_type_id, created_by, created_on)
VALUES (15, 'Harry Potter and the Philosopher''''s Stone', 'J.K. Rowling', '9780545790352', 'The first book in the beloved series follows an orphaned boy who discovers he''''s a wizard on his eleventh birthday. Whisked away to Hogwarts School of Witchcraft and Wizardry, Harry Potter finds friendship, adventure, and danger as he uncovers the truth about his parents'''' deaths and confronts the dark wizard responsible for his lightning-bolt scar.', 6, 7, 1, 'system', CURRENT TIMESTAMP);

INSERT INTO books (id, title, author, isbn, description, genre_id, publisher_id, book_type_id, created_by, created_on)
VALUES (16, 'Outliers: The Story of Success', 'Malcolm Gladwell', '9780316204361', 'Challenging conventional wisdom about success, Gladwell examines the factors that contribute to high achievement. Through compelling case studies—from Beatles and Bill Gates to cultural legacies and educational advantages—he demonstrates that success isn''''t just about individual merit, but also about timing, opportunity, cultural background, and accumulated advantages.', 8, 8, 2, 'system', CURRENT TIMESTAMP);

INSERT INTO books (id, title, author, isbn, description, genre_id, publisher_id, book_type_id, created_by, created_on)
VALUES (17, 'Beloved', 'Toni Morrison', '9781400033416', 'Set after the American Civil War, this Pulitzer Prize-winning novel tells the story of Sethe, a former slave haunted by the trauma of her past and the ghost of her baby daughter. Morrison''''s lyrical prose explores the psychological effects of slavery, the power of community, and the complexity of maternal love in the face of impossible choices.', 4, 9, 1, 'system', CURRENT TIMESTAMP);

INSERT INTO books (id, title, author, isbn, description, genre_id, publisher_id, book_type_id, created_by, created_on)
VALUES (18, 'The Shining', 'Stephen King', '9781501156700', 'When Jack Torrance becomes winter caretaker at the isolated Overlook Hotel, he sees it as an opportunity to reconnect with his family and work on his writing. But as snowbound isolation sets in, the hotel''''s sinister influence awakens Jack''''s demons while his psychically gifted son Danny perceives terrifying premonitions from both the hotel''''s past and future.', 5, 10, 1, 'system', CURRENT TIMESTAMP);

INSERT INTO books (id, title, author, isbn, description, genre_id, publisher_id, book_type_id, created_by, created_on)
VALUES (19, 'Americanah', 'Chimamanda Ngozi Adichie', '9780307455925', 'This powerful novel follows Ifemelu and Obinze, young lovers who depart military-ruled Nigeria for the West. Ifemelu heads to America, where she encounters racism and discovers what it means to be Black in the U.S., while Obinze plunges into a dangerous undocumented life in London. Years later, they reunite in a newly democratic Nigeria.', 4, 1, 2, 'system', CURRENT TIMESTAMP);

INSERT INTO books (id, title, author, isbn, description, genre_id, publisher_id, book_type_id, created_by, created_on)
VALUES (20, 'Norwegian Wood', 'Haruki Murakami', '9780307476463', 'Set in Tokyo during the late 1960s, this nostalgic story follows Toru Watanabe, who is devoted to the beautiful but emotionally troubled Naoko. Their relationship is marked by the tragic suicide of their best friend years before. As Naoko retreats into herself, Toru is drawn to the outgoing, lively Midori, forcing him to choose between his past and his future.', 4, 2, 1, 'system', CURRENT TIMESTAMP);

INSERT INTO books (id, title, author, isbn, description, genre_id, publisher_id, book_type_id, created_by, created_on)
VALUES (21, 'Daring Greatly', 'Brené Brown', '9781592408412', 'Based on twelve years of research, this transformative book challenges everything we think we know about vulnerability. Brown argues that vulnerability isn''''t weakness but our clearest path to courage and meaningful connection. Through engaging storytelling and research, she explores how embracing our imperfections can transform the way we live, love, parent, and lead.', 8, 3, 2, 'system', CURRENT TIMESTAMP);

INSERT INTO books (id, title, author, isbn, description, genre_id, publisher_id, book_type_id, created_by, created_on)
VALUES (22, 'A Game of Thrones', 'George R.R. Martin', '9780553593716', 'In this epic fantasy series opener, noble families fight for control of the Seven Kingdoms of Westeros. Political and sexual intrigue abound as the Stark, Lannister, and Targaryen families navigate a landscape where seasons last for years and an ancient evil awakens beyond the great Wall in the frozen north. Loyalty, honor, and betrayal drive this complex tale.', 6, 4, 1, 'system', CURRENT TIMESTAMP);

INSERT INTO books (id, title, author, isbn, description, genre_id, publisher_id, book_type_id, created_by, created_on)
VALUES (23, 'Gone Girl', 'Gillian Flynn', '9780307588371', 'When beautiful Amy Dunne disappears on her fifth wedding anniversary, her husband Nick becomes the prime suspect. Through alternating perspectives and unreliable narrators, this psychological thriller explores the tensions of a marriage gone terribly wrong. As the investigation unfolds, shocking revelations force readers to question everything they thought they knew.', 5, 5, 3, 'system', CURRENT TIMESTAMP);

INSERT INTO books (id, title, author, isbn, description, genre_id, publisher_id, book_type_id, created_by, created_on)
VALUES (24, 'Between the World and Me', 'Ta-Nehisi Coates', '9780812993547', 'Written as a letter to his teenage son, Coates confronts the painful reality of what it means to be Black in America. Through personal narrative and historical context, he explores how American society has built and sustained racial oppression, offering a powerful framework for understanding our nation''''s history and present crisis around race and identity.', 1, 6, 2, 'system', CURRENT TIMESTAMP);

INSERT INTO books (id, title, author, isbn, description, genre_id, publisher_id, book_type_id, created_by, created_on)
VALUES (25, 'The Goldfinch', 'Donna Tartt', '9780316055437', 'After surviving an accident that kills his mother, thirteen-year-old Theo Decker is taken in by a wealthy family. Adrift in his new life and haunted by grief, he clings to a small painting that reminds him of his mother. This Pulitzer Prize-winning novel follows Theo''''s journey through loss, friendship, love, and redemption across decades and continents.', 4, 7, 1, 'system', CURRENT TIMESTAMP);

INSERT INTO books (id, title, author, isbn, description, genre_id, publisher_id, book_type_id, created_by, created_on)
VALUES (26, 'The Underground Railroad', 'Colson Whitehead', '9780385542364', 'In this Pulitzer Prize-winning novel, Whitehead reimagines the Underground Railroad as an actual subterranean train system helping enslaved people escape to freedom. Following the harrowing journey of Cora from a Georgia plantation through different states—each representing a different facet of American racism—the book offers a powerful meditation on history and human resilience.', 4, 8, 2, 'system', CURRENT TIMESTAMP);

INSERT INTO books (id, title, author, isbn, description, genre_id, publisher_id, book_type_id, created_by, created_on)
VALUES (27, 'Circe', 'Madeline Miller', '9780062060624', 'This feminist retelling of Greek mythology follows Circe, daughter of the sun god Helios, who discovers her power of witchcraft after being banished to a remote island. Over centuries of solitude, she encounters famous mythological figures and must choose between the gods who rejected her and the mortals she''''s come to love, ultimately finding her own place in the world.', 6, 9, 1, 'system', CURRENT TIMESTAMP);

INSERT INTO books (id, title, author, isbn, description, genre_id, publisher_id, book_type_id, created_by, created_on)
VALUES (28, 'The Martian', 'Andy Weir', '9780553418026', 'When a dust storm forces his crew to evacuate Mars, astronaut Mark Watney is accidentally left behind, presumed dead. With limited supplies and no way to contact Earth, he must use his ingenuity and scientific knowledge to survive the hostile planet. This gripping tale of survival combines technical accuracy with humor as Watney fights to stay alive until rescue is possible.', 6, 10, 1, 'system', CURRENT TIMESTAMP);

INSERT INTO books (id, title, author, isbn, description, genre_id, publisher_id, book_type_id, created_by, created_on)
VALUES (29, 'Little Fires Everywhere', 'Celeste Ng', '9780735224292', 'In the meticulously planned community of Shaker Heights, the Richardson family''''s orderly life is upended when enigmatic artist Mia Warren and her daughter Pearl rent a house nearby. As the families become intertwined, a custody battle over an adopted Chinese-American baby divides the town and forces everyone to examine their beliefs about motherhood, identity, and belonging.', 4, 1, 2, 'system', CURRENT TIMESTAMP);

INSERT INTO books (id, title, author, isbn, description, genre_id, publisher_id, book_type_id, created_by, created_on)
VALUES (30, 'The Devil in the White City', 'Erik Larson', '9780307408846', 'This gripping non-fiction narrative intertwines two remarkable stories set against the backdrop of the 1893 Chicago World''''s Fair: the brilliant architect Daniel Burnham who built the "White City," and H.H. Holmes, a serial killer who used the fair to lure victims to his "Murder Castle." Larson masterfully blends beauty and horror in this meticulously researched historical account.', 3, 2, 1, 'system', CURRENT TIMESTAMP);

INSERT INTO books (id, title, author, isbn, description, genre_id, publisher_id, book_type_id, created_by, created_on)
VALUES (31, 'The Nightingale', 'Kristin Hannah', '9780312577223', 'Set in France during World War II, this powerful novel follows two sisters—one rebellious, one traditional—as they each embark on dangerous paths to survival under Nazi occupation. Vianne must protect her daughter when a German officer requisitions her home, while Isabelle joins the Resistance, risking her life to save others. A heart-wrenching exploration of courage, resilience, and sisterhood.', 4, 3, 1, 'system', CURRENT TIMESTAMP);

INSERT INTO books (id, title, author, isbn, description, genre_id, publisher_id, book_type_id, created_by, created_on)
VALUES (32, 'A Gentleman in Moscow', 'Amor Towles', '9780670026197', 'In 1922, Count Alexander Rostov is sentenced by a Bolshevik tribunal to house arrest in Moscow''''s grand Metropol Hotel. As decades pass outside his door, the Count crafts a new life of purpose within his confined circumstances, forming unexpected friendships and discovering the true meaning of home. Towles'''' elegant prose creates a captivating world within the hotel''''s walls.', 4, 4, 2, 'system', CURRENT TIMESTAMP);

INSERT INTO books (id, title, author, isbn, description, genre_id, publisher_id, book_type_id, created_by, created_on)
VALUES (33, 'All the Light We Cannot See', 'Anthony Doerr', '9781501173219', 'This Pulitzer Prize-winning novel follows a blind French girl and a German boy whose paths collide in occupied France during World War II. Marie-Laure takes refuge with her great-uncle in Saint-Malo, carrying a dangerous secret, while Werner, a radio expert, tracks the resistance. Their stories converge in a meditation on the power of human connection amid darkness.', 4, 5, 1, 'system', CURRENT TIMESTAMP);

INSERT INTO books (id, title, author, isbn, description, genre_id, publisher_id, book_type_id, created_by, created_on)
VALUES (34, 'Where the Crawdads Sing', 'Delia Owens', '9780735219090', 'For years, rumors of the "Marsh Girl" haunted the quiet fishing village of Barkley Cove. Kya Clark, abandoned by her family, raised herself in the marshlands, becoming both naturalist and outcast. When the town''''s golden boy is found dead, suspicion falls on Kya. This coming-of-age story explores loneliness, survival, and the deep human need for connection.', 4, 6, 2, 'system', CURRENT TIMESTAMP);

INSERT INTO books (id, title, author, isbn, description, genre_id, publisher_id, book_type_id, created_by, created_on)
VALUES (35, 'Born a Crime', 'Trevor Noah', '9780399588174', 'In this compelling memoir, comedian Trevor Noah recounts his childhood in South Africa during the twilight of apartheid. Born to a Black mother and white father when such relationships were punishable by imprisonment, Noah''''s very existence was evidence of his parents'''' crime. With wit and insight, he shares stories of poverty, abuse, and ultimately triumph through his mother''''s unconditional love.', 1, 7, 1, 'system', CURRENT TIMESTAMP);

INSERT INTO books (id, title, author, isbn, description, genre_id, publisher_id, book_type_id, created_by, created_on)
VALUES (36, 'Educated', 'Tara Westover', '9780399590504', 'Born to survivalist parents in the mountains of Idaho, Tara Westover was seventeen before she ever set foot in a classroom. Her quest for knowledge took her from self-education to Harvard and Cambridge. This extraordinary memoir explores the transformative power of education and the price of severing family ties to become your authentic self.', 1, 8, 2, 'system', CURRENT TIMESTAMP);

INSERT INTO books (id, title, author, isbn, description, genre_id, publisher_id, book_type_id, created_by, created_on)
VALUES (37, 'Pachinko', 'Min Jin Lee', '9781455563920', 'This sweeping saga follows four generations of a Korean family who move to Japan in the early 20th century. Beginning with Sunja, a pregnant teenager who refuses to be bought, the novel chronicles the family''''s struggles with identity and belonging as ethnic Koreans in Japan. Through war, peace, and cultural upheaval, they persevere against discrimination and historical forces beyond their control.', 4, 9, 1, 'system', CURRENT TIMESTAMP);

INSERT INTO books (id, title, author, isbn, description, genre_id, publisher_id, book_type_id, created_by, created_on)
VALUES (38, 'The Vanishing Half', 'Brit Bennett', '9780525536291', 'The Vignes twin sisters run away from their small, southern Black community at sixteen. Years later, one sister lives with her Black daughter in the same town she tried to escape, while the other secretly passes for white. This stunning novel explores the lasting influence of the past as it shapes decisions, desires, and expectations across generations, examining the American history of passing and racial identity.', 4, 10, 2, 'system', CURRENT TIMESTAMP);

INSERT INTO books (id, title, author, isbn, description, genre_id, publisher_id, book_type_id, created_by, created_on)
VALUES (39, 'Before We Were Yours', 'Lisa Wingate', '9780425284681', 'Based on a notorious real-life scandal, this novel follows Rill Foss, who at twelve years old must protect her four siblings when they''''re taken from their family''''s Mississippi River shantyboat to a Tennessee Children''''s Home Society orphanage. Decades later, a privileged young woman uncovers the shocking truth about her family''''s past, revealing the heartbreaking injustices that changed so many lives.', 4, 1, 1, 'system', CURRENT TIMESTAMP);

INSERT INTO books (id, title, author, isbn, description, genre_id, publisher_id, book_type_id, created_by, created_on)
VALUES (40, 'Homegoing', 'Yaa Gyasi', '9781101947135', 'This remarkable debut novel follows the parallel paths of two half-sisters born in eighteenth-century Ghana and their descendants. One sister marries a British slaver, while the other is sold into slavery. Through eight generations and 300 years of history, Gyasi explores how the legacy of slavery affects each new generation, from the Gold Coast of Africa to the plantations of Mississippi to modern-day Harlem.', 4, 2, 2, 'system', CURRENT TIMESTAMP);

INSERT INTO books (id, title, author, isbn, description, genre_id, publisher_id, book_type_id, created_by, created_on)
VALUES (41, 'A Man Called Ove', 'Fredrik Backman', '9781476738024', 'Meet Ove, a curmudgeon with staunch principles, strict routines, and a short fuse who finds his solitary world turned upside down when a boisterous young family moves in next door. Behind his cranky exterior lies a story of true love and profound grief. This heartwarming tale shows how unexpected friendships can change one''''s life and reveals the impact we have on those around us.', 4, 3, 1, 'system', CURRENT TIMESTAMP);

INSERT INTO books (id, title, author, isbn, description, genre_id, publisher_id, book_type_id, created_by, created_on)
VALUES (42, 'American Dirt', 'Jeanine Cummins', '9781250209764', 'Lydia Quixano Pérez lives a comfortable life in Acapulco with her journalist husband and son, until he publishes an exposé on a powerful drug cartel leader. After violence claims her entire family, Lydia and her son flee north toward the United States. This gripping story illuminates the experience of migrants forced to leave their homes in search of safety and a better life.', 4, 4, 2, 'system', CURRENT TIMESTAMP);

INSERT INTO books (id, title, author, isbn, description, genre_id, publisher_id, book_type_id, created_by, created_on)
VALUES (43, 'The Night Circus', 'Erin Morgenstern', '9780385534635', 'The circus arrives without warning, appearing at night and open only from sunset to sunrise. Within its black-and-white striped tents lies an utterly unique experience, a feast for the senses. But behind the scenes, two young magicians, Celia and Marco, compete in a dangerous game orchestrated by their instructors, unaware that only one can survive as they fall deeply in love.', 6, 5, 1, 'system', CURRENT TIMESTAMP);

INSERT INTO books (id, title, author, isbn, description, genre_id, publisher_id, book_type_id, created_by, created_on)
VALUES (44, 'Mexican Gothic', 'Silvia Moreno-Garcia', '9780525620785', 'When socialite Noemí receives a frantic letter from her newly-wed cousin begging to be rescued from a mysterious doom, she heads to High Place, a distant house in the Mexican countryside. There she finds a decaying mansion, a strange family, and a house that begins to invade her dreams with visions of blood and doom. This atmospheric horror novel blends elements of gothic fiction with Mexican folklore.', 6, 6, 2, 'system', CURRENT TIMESTAMP);

INSERT INTO books (id, title, author, isbn, description, genre_id, publisher_id, book_type_id, created_by, created_on)
VALUES (45, 'A Darker Shade of Magic', 'V.E. Schwab', '9780765387561', 'Kell is one of the last Antari—magicians with the rare ability to travel between parallel Londons: Red, Grey, White, and once upon a time, Black. After an exchange goes awry, Kell escapes to Grey London and encounters Delilah Bard, a cut-purse with lofty aspirations. Now perilous magic is afoot, and treachery lurks at every turn as the two must work together to save all worlds.', 6, 7, 1, 'system', CURRENT TIMESTAMP);

INSERT INTO books (id, title, author, isbn, description, genre_id, publisher_id, book_type_id, created_by, created_on)
VALUES (46, 'The Fifth Season', 'N.K. Jemisin', '9780316229296', 'In a world where catastrophic climate events threaten civilization, people with the ability to control energy—orogenes—are both feared and exploited. When Essun discovers her husband has murdered their son and kidnapped their daughter upon learning they are orogenes, she sets out on a mission of rescue and revenge across a continent literally tearing itself apart. The first book in Jemisin''''s revolutionary trilogy.', 6, 8, 2, 'system', CURRENT TIMESTAMP);

INSERT INTO books (id, title, author, isbn, description, genre_id, publisher_id, book_type_id, created_by, created_on)
VALUES (47, 'Dark Matter', 'Blake Crouch', '9781101904220', 'Jason Dessen, a physics professor, is knocked unconscious and awakens to find himself in a world where his life took a dramatically different path. In this alternate reality, he never married his wife and never had his son, but instead achieved professional success beyond his wildest dreams. This mind-bending thriller explores questions of identity, choice, and the road not taken.', 6, 9, 1, 'system', CURRENT TIMESTAMP);

INSERT INTO books (id, title, author, isbn, description, genre_id, publisher_id, book_type_id, created_by, created_on)
VALUES (48, 'All Systems Red', 'Martha Wells', '9781250229861', 'In this Hugo Award-winning novella, a self-aware security android who has hacked its own governor module and nicknamed itself "Murderbot" just wants to be left alone to watch entertainment feeds. When a neighboring mission goes dark, Murderbot must overcome its antisocial tendencies to protect the humans it''''s assigned to protect, even though it doesn''''t particularly like them.', 6, 10, 2, 'system', CURRENT TIMESTAMP);

INSERT INTO books (id, title, author, isbn, description, genre_id, publisher_id, book_type_id, created_by, created_on)
VALUES (49, 'A Walk in the Woods', 'Bill Bryson', '9780767908184', 'After spending twenty years in England, Bill Bryson returns to America and decides to reacquaint himself with his native country by hiking the 2,100-mile Appalachian Trail. Accompanied by his friend Stephen Katz, Bryson confronts nature at its most uncompromising. With his trademark humor, he chronicles their misadventures while offering fascinating insights into the trail''''s history, ecology, and the characters they meet along the way.', 7, 1, 1, 'system', CURRENT TIMESTAMP);

INSERT INTO books (id, title, author, isbn, description, genre_id, publisher_id, book_type_id, created_by, created_on)
VALUES (50, 'Eat, Pray, Love', 'Elizabeth Gilbert', '9780143038412', 'After a painful divorce and personal crisis, Elizabeth Gilbert embarks on a year-long journey of self-discovery. She spends four months in Italy savoring food and language, four months in India exploring spirituality at an ashram, and four months in Bali seeking balance and unexpected love. This intimate memoir chronicles her quest to find pleasure, devotion, and equilibrium in her life.', 7, 2, 2, 'system', CURRENT TIMESTAMP);

INSERT INTO books (id, title, author, isbn, description, genre_id, publisher_id, book_type_id, created_by, created_on)
VALUES (51, 'The Great Railway Bazaar', 'Paul Theroux', '9780618658978', 'In this classic travel narrative, Theroux recounts his epic journey by rail through Asia. Beginning in London, he travels through Europe, the Middle East, India, and Southeast Asia, circling back through the Soviet Union. With keen observation and wit, he captures the essence of train travel and the diverse landscapes, cultures, and characters he encounters, creating an unforgettable portrait of a continent in transition.', 7, 3, 1, 'system', CURRENT TIMESTAMP);

INSERT INTO books (id, title, author, isbn, description, genre_id, publisher_id, book_type_id, created_by, created_on)
VALUES (52, 'Wild', 'Cheryl Strayed', '9780307476074', 'At twenty-two, Cheryl Strayed thought she had lost everything. After her mother''''s death, her family scattered and her marriage crumbled. With nothing to lose, she made the impulsive decision to hike the Pacific Crest Trail from the Mojave Desert to Washington State—alone, with no experience. This powerful memoir chronicles her physical and psychological journey toward healing and self-discovery.', 7, 4, 2, 'system', CURRENT TIMESTAMP);

INSERT INTO books (id, title, author, isbn, description, genre_id, publisher_id, book_type_id, created_by, created_on)
VALUES (53, 'Into the Wild', 'Jon Krakauer', '9780385494786', 'In April 1992, Christopher McCandless hitchhiked to Alaska and walked alone into the wilderness. Four months later, his decomposed body was found by a moose hunter. This compelling narrative explores what drove this young man to abandon his possessions, give away his savings, and seek radical freedom in the wilderness, ultimately leading to his tragic death in an abandoned bus in the Alaskan interior.', 7, 5, 1, 'system', CURRENT TIMESTAMP);

INSERT INTO books (id, title, author, isbn, description, genre_id, publisher_id, book_type_id, created_by, created_on)
VALUES (54, 'Under the Tuscan Sun', 'Frances Mayes', '9780767900386', 'When American professor Frances Mayes buys and restores an abandoned villa in the Tuscan countryside, she begins a life-changing journey. Through evocative descriptions of the landscape, food, and local characters, she captures the essence of Tuscany while reflecting on the pleasures of building a new life in a foreign land. Part travel memoir, part renovation story, and part celebration of Italian culture.', 7, 6, 2, 'system', CURRENT TIMESTAMP);

INSERT INTO books (id, title, author, isbn, description, genre_id, publisher_id, book_type_id, created_by, created_on)
VALUES (55, 'The Very Hungry Caterpillar', 'Eric Carle', '9780399226908', 'This beloved children''''s classic follows a caterpillar as it eats its way through an increasing amount of food before pupating and emerging as a beautiful butterfly. With its distinctive collage illustrations and die-cut pages, this simple tale teaches children about numbers, days of the week, foods, and the life cycle of a butterfly in an engaging, accessible way.', 2, 7, 3, 'system', CURRENT TIMESTAMP);

