-- Advance sequences to start from 101
ALTER TABLE CUSTOMERS ALTER COLUMN ID RESTART WITH 101;
ALTER TABLE ADDRESSES ALTER COLUMN ID RESTART WITH 101;
ALTER TABLE GENRES ALTER COLUMN ID RESTART WITH 101;
ALTER TABLE PUBLISHERS ALTER COLUMN ID RESTART WITH 101;
ALTER TABLE BOOK_TYPES ALTER COLUMN ID RESTART WITH 101;
ALTER TABLE CONDITIONS ALTER COLUMN ID RESTART WITH 101;
ALTER TABLE BOOKS ALTER COLUMN ID RESTART WITH 101;
ALTER TABLE LISTINGS ALTER COLUMN ID RESTART WITH 101;
ALTER TABLE ORDERS ALTER COLUMN ID RESTART WITH 101;
ALTER TABLE ORDER_ITEMS ALTER COLUMN ID RESTART WITH 101;
ALTER TABLE SHOPPING_CART_ITEMS ALTER COLUMN ID RESTART WITH 101;

