-- =============================================================================
-- Optimiser statistics (Oracle equivalent: DBMS_STATS.GATHER_SCHEMA_STATS)
-- =============================================================================
-- Without this the Db2 optimiser plans against default cardinalities and the
-- join-heavy reporting routines in 04_complex_schema_db2_v2.sql can choose
-- nested-loop plans over the correct hash joins.
CALL SYSPROC.ADMIN_CMD('RUNSTATS ON TABLE DEMO.BOOKS       WITH DISTRIBUTION AND DETAILED INDEXES ALL');
CALL SYSPROC.ADMIN_CMD('RUNSTATS ON TABLE DEMO.LISTINGS    WITH DISTRIBUTION AND DETAILED INDEXES ALL');
CALL SYSPROC.ADMIN_CMD('RUNSTATS ON TABLE DEMO.CUSTOMERS   WITH DISTRIBUTION AND DETAILED INDEXES ALL');
CALL SYSPROC.ADMIN_CMD('RUNSTATS ON TABLE DEMO.ORDERS      WITH DISTRIBUTION AND DETAILED INDEXES ALL');
CALL SYSPROC.ADMIN_CMD('RUNSTATS ON TABLE DEMO.ORDER_ITEMS WITH DISTRIBUTION AND DETAILED INDEXES ALL');

CONNECT RESET;

